import{_ as o,o as a,c as n,a0 as t}from"./chunks/framework.DW5bL-_G.js";const p=JSON.parse('{"title":"Changelog","description":"Release notes for ew-color-picker, including fixes, features and documentation updates.","frontmatter":{"title":"Changelog","description":"Release notes for ew-color-picker, including fixes, features and documentation updates."},"headers":[],"relativePath":"en/guide/changelog.md","filePath":"en/guide/changelog.md"}'),i={name:"en/guide/changelog.md"};function r(d,e,l,c,s,h){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_2-0-1" tabindex="-1">2.0.1 <a class="header-anchor" href="#_2-0-1" aria-label="Permalink to &quot;2.0.1&quot;">​</a></h2><blockquote><p>These changes are merged into the main branch and reflected in the docs site. The npm packages are not published yet and will be released together with further fixes.</p></blockquote><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed plugin switches being overridden: <code>ewColorPickerPanel: false</code> and <code>ewColorPickerColorMode: false</code> (or an object config) were replaced by defaults and did not take effect</li><li>Panel container now declares <code>box-sizing: content-box</code>, no longer relying on the host global <code>box-sizing</code> reset</li><li>Removed viewport media queries (<code>max-width: 768px</code>) that hard-coded panel, input and preset sizes; inner sizes are now driven solely by <code>--panel-width</code> / <code>--panel-height</code></li><li>Predefined swatches now use flex wrapping; removed the hard-coded &quot;10 per row&quot; rule that caused wrong wrapping when the swatch count or container width changed</li></ul><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>New <code>appendTo</code> option: mount the panel container into <code>document.body</code> or any container to avoid <code>overflow</code> clipping by dialogs, drawers and scroll containers. The panel then uses viewport-relative positioning, still honors <code>panelPlacement</code> with boundary flipping, and re-positions on scroll or resize</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Corrected predefined swatch and number input class names to match the source</li><li>Removed the non-existent nested <code>ewColorPickerBox</code> config in favor of top-level options</li><li>Corrected the prerequisites of <code>autoPanelPosition</code></li><li>Added <code>appendTo</code> documentation (Chinese and English)</li></ul><h2 id="_2-0-0" tabindex="-1">2.0.0 <a class="header-anchor" href="#_2-0-0" aria-label="Permalink to &quot;2.0.0&quot;">​</a></h2><p>First stable release: core + plugin architecture, 14 packages (13 scoped packages plus the unscoped <code>ew-color-picker</code> entry package), bilingual docs site and live demo.</p>',11)])])}const g=o(i,[["render",r]]);export{p as __pageData,g as default};
